#define MAX(a, b) ((a) > (b) ? (a) : (b)) 
int
foo (int n, int* a)
{
    int max = 0;
    for (int i = 0; i != n; i++)
    {
        int tmp = a[i];
        if (tmp < 0)
          max = MAX (-tmp, max);
        else
          max = MAX (tmp, max);
    }
    return max;
}

int
foo1 (int n, int* a)
{
